select extensions.plan(16);
set local role anon;
select extensions.throws_like('select * from public.usuarios','%permission denied%','Anónimo no consulta perfiles');
select extensions.throws_like('select * from public.mercado_prestamos','%permission denied%','Anónimo no consulta el mercado');
reset role;
set local request.jwt.claims='{"sub":"00000000-0000-4000-8000-000000000013","role":"authenticated"}';
set local role authenticated;
select extensions.is((select count(*)::int from public.usuarios),1,'Cada usuario consulta su perfil completo');
select extensions.is((select count(*)::int from public.prestamos),0,'Un extraño no consulta expedientes completos');
select extensions.is((select count(*)::int from public.mercado_prestamos),1,'El mercado muestra la solicitud financiándose');
select extensions.is((select count(*)::int from public.mercado_etapas),2,'El mercado muestra el plan de etapas');
select extensions.is((select count(*)::int from public.perfiles_publicos where id='00000000-0000-4000-8000-000000000001'),1,'Perfil público del emprendedor visible');
select extensions.throws_like('select correo from public.perfiles_publicos','%does not exist%','La proyección pública no contiene correo');
select extensions.throws_like('select carnet_anverso_url from public.perfiles_publicos','%does not exist%','La proyección pública no contiene carnet');
select extensions.throws_like($$update public.usuarios set rol='admin' where id=auth.uid()$$,'%autorizados%','Un usuario no se convierte en administrador');
select extensions.throws_like($$update public.usuarios set estado_verificacion='verificado',estrellas=5 where id=auth.uid()$$,'%autorizados%','Un usuario no cambia verificación ni reputación');
select extensions.lives_ok($$update public.usuarios set nombre='Nombre actualizado' where id=auth.uid()$$,'El usuario puede cambiar su nombre');
reset role;
set local request.jwt.claims='{"sub":"00000000-0000-4000-8000-000000000022","role":"authenticated"}';
set local role authenticated;
select extensions.is((select count(*)::int from public.prestamos),1,'Soporte consulta expedientes');
with cambio as (update public.parametros set valor=9 where clave='tasa_maxima_anual' returning *) select extensions.is((select count(*)::int from cambio),0,'Soporte no cambia parámetros');
select extensions.lives_ok($$insert into public.eventos_prestamo(prestamo_id,usuario_id,tipo,detalle) values('00000000-0000-4000-8000-000000000101',auth.uid(),'intervencion_soporte','{"accion":"consulta"}')$$,'Soporte registra una intervención propia');
select extensions.throws_like($$insert into public.eventos_prestamo(prestamo_id,usuario_id,tipo) values('00000000-0000-4000-8000-000000000101',auth.uid(),'cuota_pagada')$$,'%Fondea%','Soporte no fabrica eventos de dinero');
reset role;
select * from extensions.finish();
